// Initialize distances
for (int i = 0; i < n; i++) {
    dist[i] = (i == start) ? 0 : INT_MAX;
}

PriorityQueue<std::pair<int, int>> pq;  // {distance, node}
pq.enqueue({0, start});

while (!pq.isEmpty()) {
    auto current = pq.dequeue();
    int currentDist = current.first;
    int u = current.second;

    // If we've already found a better path, skip
    if (currentDist > dist[u]) continue;

    // Check all neighbors
    for (int v = 0; v < n; v++) {
        if (graph[u][v] != 0) {  // If there's an edge
            int newDist = currentDist + graph[u][v];
            if (newDist < dist[v]) {
                dist[v] = newDist;
                pq.enqueue({newDist, v});
            }
        }
    }
}

